-- ============================================================
-- barber-system - Estrutura do banco de dados (MySQL 8+)
--
-- Este arquivo é OPCIONAL. Ele serve para quem preferir criar as
-- tabelas "na mão" pelo phpMyAdmin/MySQL Workbench, sem rodar o
-- Sequelize. Se você usar o comando abaixo, nem precisa dele:
--
--     npm run db:sync
--
-- Como usar este arquivo:
--   1. Crie o banco:  CREATE DATABASE dbbarber
--                      CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
--   2. Selecione o banco (USE dbbarber;) e importe este arquivo.
--   3. Rode "npm run db:seed" para cadastrar o administrador e os
--      dados de exemplo.
--
-- Observação: a tabela "sessoes" guarda os logins (express-session).
-- Ela é criada automaticamente pelo Sequelize no "npm run db:sync".
-- ============================================================

CREATE TABLE IF NOT EXISTS `usuarios` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `email` VARCHAR(255) NOT NULL UNIQUE, `senha` VARCHAR(255) NOT NULL, `role` VARCHAR(255) NOT NULL DEFAULT 'cliente', `ativo` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `cargos` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `descricao` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `funcionarios` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `telefone` VARCHAR(255), `email` VARCHAR(255), `comissao` DECIMAL(5,2) NOT NULL DEFAULT 40, `ativo` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `cargo_id` INTEGER, `user_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`cargo_id`) REFERENCES `cargos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (`user_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `clientes` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `telefone` VARCHAR(255), `email` VARCHAR(255), `data_nascimento` DATE, `observacoes` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `user_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`user_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `categorias_servico` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `servicos` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `descricao` TEXT, `preco` DECIMAL(10,2) NOT NULL DEFAULT 0, `duracao` INTEGER NOT NULL DEFAULT 30, `icone` VARCHAR(255) DEFAULT 'bi-scissors', `ativo` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `categoria_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`categoria_id`) REFERENCES `categorias_servico` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `categorias_produto` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `produtos` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `descricao` TEXT, `preco_custo` DECIMAL(10,2) NOT NULL DEFAULT 0, `preco_venda` DECIMAL(10,2) NOT NULL DEFAULT 0, `estoque` INTEGER NOT NULL DEFAULT 0, `estoque_minimo` INTEGER NOT NULL DEFAULT 3, `ativo` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `categoria_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`categoria_id`) REFERENCES `categorias_produto` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `fornecedores` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `cnpj` VARCHAR(255), `telefone` VARCHAR(255), `email` VARCHAR(255), `endereco` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `disponibilidades` (`id` INTEGER NOT NULL auto_increment , `dia_semana` INTEGER NOT NULL, `hora_inicio` VARCHAR(5) NOT NULL DEFAULT '09:00', `hora_fim` VARCHAR(5) NOT NULL DEFAULT '19:00', `ativo` TINYINT(1) NOT NULL DEFAULT true, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `funcionario_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`funcionario_id`) REFERENCES `funcionarios` (`id`) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `agendamentos` (`id` INTEGER NOT NULL auto_increment , `data` DATE NOT NULL, `hora` VARCHAR(5) NOT NULL, `status` VARCHAR(255) NOT NULL DEFAULT 'pendente', `valor_total` DECIMAL(10,2) NOT NULL DEFAULT 0, `observacoes` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `cliente_id` INTEGER, `funcionario_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (`funcionario_id`) REFERENCES `funcionarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `agendamento_servicos` (`id` INTEGER NOT NULL auto_increment , `nome_servico` VARCHAR(255) NOT NULL, `preco` DECIMAL(10,2) NOT NULL DEFAULT 0, `duracao` INTEGER NOT NULL DEFAULT 30, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `agendamento_id` INTEGER, `servico_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`agendamento_id`) REFERENCES `agendamentos` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (`servico_id`) REFERENCES `servicos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `vendas` (`id` INTEGER NOT NULL auto_increment , `data` DATE NOT NULL, `valor_total` DECIMAL(10,2) NOT NULL DEFAULT 0, `forma_pagamento` VARCHAR(255) NOT NULL DEFAULT 'dinheiro', `observacoes` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `cliente_id` INTEGER, `funcionario_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`cliente_id`) REFERENCES `clientes` (`id`) ON DELETE SET NULL ON UPDATE CASCADE, FOREIGN KEY (`funcionario_id`) REFERENCES `funcionarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `venda_itens` (`id` INTEGER NOT NULL auto_increment , `descricao` VARCHAR(255) NOT NULL, `quantidade` INTEGER NOT NULL DEFAULT 1, `preco_unitario` DECIMAL(10,2) NOT NULL DEFAULT 0, `subtotal` DECIMAL(10,2) NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `venda_id` INTEGER, `produto_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`venda_id`) REFERENCES `vendas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `compras` (`id` INTEGER NOT NULL auto_increment , `data` DATE NOT NULL, `valor_total` DECIMAL(10,2) NOT NULL DEFAULT 0, `observacoes` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `fornecedor_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`fornecedor_id`) REFERENCES `fornecedores` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `compra_itens` (`id` INTEGER NOT NULL auto_increment , `descricao` VARCHAR(255) NOT NULL, `quantidade` INTEGER NOT NULL DEFAULT 1, `preco_unitario` DECIMAL(10,2) NOT NULL DEFAULT 0, `subtotal` DECIMAL(10,2) NOT NULL DEFAULT 0, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `compra_id` INTEGER, `produto_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`compra_id`) REFERENCES `compras` (`id`) ON DELETE CASCADE ON UPDATE CASCADE, FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `movimentos_estoque` (`id` INTEGER NOT NULL auto_increment , `data` DATE NOT NULL, `tipo` VARCHAR(255) NOT NULL DEFAULT 'entrada', `quantidade` INTEGER NOT NULL DEFAULT 0, `motivo` VARCHAR(255), `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, `produto_id` INTEGER, PRIMARY KEY (`id`), FOREIGN KEY (`produto_id`) REFERENCES `produtos` (`id`) ON DELETE SET NULL ON UPDATE CASCADE) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `contas` (`id` INTEGER NOT NULL auto_increment , `tipo` VARCHAR(255) NOT NULL DEFAULT 'pagar', `descricao` VARCHAR(255) NOT NULL, `valor` DECIMAL(10,2) NOT NULL DEFAULT 0, `vencimento` DATE NOT NULL, `pago` TINYINT(1) NOT NULL DEFAULT false, `data_pagamento` DATE, `observacoes` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `comentarios` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL, `texto` TEXT NOT NULL, `nota` INTEGER NOT NULL DEFAULT 5, `aprovado` TINYINT(1) NOT NULL DEFAULT false, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `configuracoes_site` (`id` INTEGER NOT NULL auto_increment , `nome` VARCHAR(255) NOT NULL DEFAULT 'Barber VIP', `slogan` VARCHAR(255) DEFAULT 'Tradição, estilo e atitude', `logo` VARCHAR(255), `og_imagem` VARCHAR(255), `hero_titulo` VARCHAR(255) DEFAULT 'Seu estilo, no horário que você quiser.', `hero_subtitulo` TEXT, `sobre` TEXT, `telefone` VARCHAR(255), `whatsapp` VARCHAR(255), `email` VARCHAR(255), `endereco` VARCHAR(255), `horario_funcionamento` VARCHAR(255) DEFAULT 'Segunda a sábado, das 09h às 19h', `instagram` VARCHAR(255), `facebook` VARCHAR(255), `titulo_seo` VARCHAR(255) DEFAULT 'Barber VIP | Barbearia premium e agendamento online', `descricao_seo` TEXT, `palavras_chave` VARCHAR(255) DEFAULT 'barbearia, corte de cabelo, barba, agendamento online, barbeiro', `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`id`)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS `sessoes` (`sid` VARCHAR(36) , `expires` DATETIME, `data` TEXT, `created_at` DATETIME NOT NULL, `updated_at` DATETIME NOT NULL, PRIMARY KEY (`sid`)) ENGINE=InnoDB;
